	public static void main(String args[]) {

		int n = sc.nextInt();
		ArrayList<Integer> list = new ArrayList<>();
		for (int i=0; i<n; i++) list.add(sc.nextInt());


		int count = 0;
		for (int i=0; i<n-1; i++) {

