import java.util.Scanner;

public class Main {

	static int binarySearch(int[] a, int[] b) {
		int counter = 0;
		int mid = 0;
		for(int i=0; i<b.length; i++){
			int L = 0;
			int R = a.length-1;

			while(L<=R)
			{
				mid = (L+R)/2;
//				System.out.println("mid: "+ mid);
				if(b[i]==a[mid])
				{
					counter++;
					break;
				}
				else if(b[i]<a[mid])
				{
					R = mid-1;
				}
				else if(b[i]>a[mid])
				{
					L = mid+1;
				}
			}		
		}
		return counter;
	}

