		while(true) {
			int n = sc.nextInt();

			if(n == 0) break;

			int[] scores = new int[n];

			int sum = 0;
			for (int i = 0; i < n; i++) {
				scores[i] = sc.nextInt();
				sum += scores[i];
			}
