		long ex = N - (A + B) * mult;
		if(A == 0){
			ans = 0;
		}else{
			ans = mult * A;
			if(ex <= A){
				ans += ex;
			}else{
				ans += A;
			}
		}
		System.out.println(ans);
	}
}

